export const source =
  "from contextlib import asynccontextmanager\nfrom fastapi import FastAPI, APIRouter, Depends, Security, WebSocket\nfrom fastapi.security import OAuth2PasswordBearer, SecurityScopes\nfrom starlette.requests import Request\nfrom starlette.routing import Host\nfrom starlette.responses import JSONResponse\nfrom pydantic import BaseModel\ntrace=[]\ncalls=[]\nasync def original_settings(): return 'unconfigured'\nasync def configured_settings(): return 'native-settings'\n@asynccontextmanager\nasync def root_life(app):\n    trace.append('root.enter')\n    try: yield {'original_lifespan':True}\n    finally:\n        trace.append('root.exit')\n        import pathlib,json\n        pathlib.Path('.checktrail').mkdir(exist_ok=True)\n        pathlib.Path('.checktrail/lifespan.closed').write_text(json.dumps(trace))\n@asynccontextmanager\nasync def included_life(app):\n    trace.append('included.enter')\n    try: yield\n    finally: trace.append('included.exit')\nclass Initialize:\n    def __init__(self,app,label='init'):self.app=app;self.label=label\n    async def __call__(self,scope,receive,send):\n        if scope['type'] in ('http','websocket'):\n            scope.setdefault('state',{})['ready']=True\n        await self.app(scope,receive,send)\nclass Authorize:\n    def __init__(self,app):self.app=app\n    async def __call__(self,scope,receive,send):\n        if scope['type']=='http' and not scope.get('state',{}).get('ready'):\n            await JSONResponse({'detail':'initialization required'},status_code=403)(scope,receive,send);return\n        await self.app(scope,receive,send)\nclass Item(BaseModel):\n    id:int\n    enabled:bool=True\nbearer=OAuth2PasswordBearer(tokenUrl='/token',scopes={'catalog:read':'Read catalog','catalog:write':'Write catalog'},auto_error=False)\nasync def token(security_scopes:SecurityScopes,token:str|None=Depends(bearer)):\n    return {'scopes':security_scopes.scopes,'token':token}\nasync def before():\n    calls.append('before')\n    return 'before'\nasync def combined(access=Security(token,scopes=['catalog:read'])):return access\nasync def socket_dependency():return 'socket-ready'\nrouter=APIRouter(prefix='/catalog',dependencies=[Depends(before)],lifespan=included_life)\n@router.get('/items',response_model=list[Item])\nasync def items(request:Request,access=Security(combined,scopes=['catalog:write']),settings=Depends(original_settings)):\n    assert request.state.original_lifespan and request.state.ready\n    assert access == {'scopes':['catalog:write','catalog:read'],'token':'original'}\n    assert settings == 'native-settings' and calls == ['before']\n    return [{'id':'1'},{'id':'2'}]\n@router.websocket('/socket')\nasync def socket(websocket:WebSocket,ready=Depends(socket_dependency)):\n    await websocket.accept();await websocket.send_json({'ready':ready});await websocket.close()\napp=FastAPI(lifespan=root_life)\napp.dependency_overrides[original_settings]=configured_settings\napp.include_router(router,prefix='/v1',dependencies=[Depends(before)])\napp.add_middleware(Authorize)\napp.add_middleware(Initialize,label='root')\n@app.get('/state')\nasync def state():return trace\nchild=FastAPI(openapi_url=None)\n@child.get('/items',response_model=Item)\nasync def mounted():return {'id':'3'}\nchild.add_middleware(Initialize,label='child')\napp.mount('/mounted',child,name='mounted')\nhosted=FastAPI(openapi_url=None)\n@hosted.get('/items')\nasync def host():return {'host':True}\napp.router.routes.insert(0,Host('api.example.test',app=hosted,name='hosted'))\n";
