export async function project(
  t: TestContext,
  program = source,
  configuration: unknown = profile,
) {
  return fixture(t, {
    "pyproject.toml": "",
    ".checktrail/lifespan.reserved": "",
    "checktrail.json": JSON.stringify({
      schemaVersion: 1,
      projects: [{ path: ".", checks: ["python.fastapi-routes"] }],
    }),
    "checktrail.fastapi.json": JSON.stringify(configuration),
    "app.py": program,
  });
}
export async function run(
  t: TestContext,
  program = source,
  configuration: unknown = profile,
) {
  return validate(await project(t, program, configuration), { trusted: true });
}
